    import time

    LANGUAGE_WRAPPER = 'Let $b = {b}$. A positive integer $n$ is called a $b$-factorial tail if there is some positive integer $m$ such that the base-$b$ representation of $m!$ ends with exactly $n$ zeros. How many positive integers less than {N} are not $b$-factorial tails?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

p_pair = rng.choice([(2, 3), (2, 5), (3, 5)])
p1, p2 = p_pair

g = gcd(p1 - 1, p2 - 1)
k1 = (p2 - 1) // g
k2 = (p1 - 1) // g

k = rng.randint(1, 2)
a1 = k1 * k
a2 = k2 * k

if rng.random() < 0.5:
    p1, p2 = p2, p1
    a1, a2 = a2, a1

N = rng.randint(1500, 4000)
b = p1**a1 * p2**a2

return {
    'p1': p1,
    'p2': p2,
    'a1': a1,
    'a2': a2,
    'b': b,
    'N': N
}

    def verifier(assign):
p1, p2, a1, a2, N = assign['p1'], assign['p2'], assign['a1'], assign['a2'], assign['N']
b = assign['b']

# Basic validation of parameters
if not (isinstance(p1, int) and isinstance(p2, int) and isinstance(a1, int) and isinstance(a2, int) and isinstance(N, int)):
    return False, None # Types must be int
if not (p1 > 1 and p2 > 1 and a1 > 0 and a2 > 0 and N > 1):
    return False, None # Values must be in valid range
if p1 == p2:
    return False, None # Primes must be distinct
if p1**a1 * p2**a2 != b:
    return False, None # b must match its definition
if not (1000 <= N <= 5000):
    return False, None # N should be in a reasonable range for difficulty

# Helper function to calculate v_p(n), the exponent of prime p in the factorization of n
def v_p(n, p):
    if n == 0:
        return float('inf') # By convention
    count = 0
    while n > 0 and n % p == 0:
        count += 1
        n //= p
    return count

# The number of trailing zeros is min(floor(E_p1(m!)/a1), floor(E_p2(m!)/a2))
# We simulate the sequence of tail counts and find which numbers are missed.
# Asymptotic rate of growth of tails is m / (a1*(p1-1)). So we need to check m up to roughly N * a1*(p1-1).
# We add a buffer to be safe.
m_max = int(N * a1 * (p1 - 1) * 1.1 + 200)

tails = {0}
E_p1 = 0
E_p2 = 0

for m in range(1, m_max + 1):
    E_p1 += v_p(m, p1)
    E_p2 += v_p(m, p2)

    current_Z = min(E_p1 // a1, E_p2 // a2)

    # Optimization: if the current tail count is already far beyond N,
    # we can be confident we have found all tails below N.
    if current_Z >= N + 100: 
        break

    tails.add(current_Z)

# Count positive integers less than N that are not in the set of tails.
non_tail_count = 0
for n in range(1, N):
    if n not in tails:
        non_tail_count += 1

return True, non_tail_count


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

